import java.util.*;
import java.io.*;

public class CF552C {
  public static int maxPowerLimit, baseNumber;
  public static HashSet<Long> sumSet;
  public static void main(String[] args) throws Exception {
    InputStreamReader isr = new InputStreamReader(System.in);
    BufferedReader br = new BufferedReader(isr);
    PrintWriter pw = new PrintWriter(System.out);

    String[] inputLine = br.readLine().split(" ");
    int baseVal = Integer.parseInt(inputLine[0]);
    long targetVal = Long.parseLong(inputLine[1]);

    int maxPower = 0;
    for (int i = 0; baseVal > 2 && i < 21; i++) {
      maxPower = i;
      if (Math.pow(baseVal, i) > 1e9) break;
    }

    sumSet = new HashSet<>();
    if (baseVal > 2) generateAllSums(0, 0, maxPower);

    boolean canForm = false;
    if (baseVal == 2) canForm = true;

    for (Long sumVal : sumSet) {
      if (sumVal >= targetVal && sumSet.contains(sumVal - targetVal)) {
        canForm = true;
        break;
      }
    }

    pw.println(canForm ? "YES" : "NO");
    pw.close();
  }

  static void generateAllSums(int index, long currentSum, int maxExp) {
    if (index > maxExp) {
      sumSet.add(currentSum);
      return;
    }
    generateAllSums(index + 1, currentSum + (long) Math.pow(baseNumber, index), maxExp);
    generateAllSums(index + 1, currentSum, maxExp);
  }
}
